 const seam=(t,i,only,full,yy)=>{const [a,b]=band(i);let y=yy!=null?yy:a+1+Math.floor(R()*Math.max(1,b-a-1)),x=full?1:1+Math.floor(R()*3);const len=full?COLS-2:5+Math.floor(R()*7);const cells=[];for(let k=0;k<len&&x<COLS-1;k++,x++){if(only.includes(T[y][x])){T[y][x]=t;cells.push([x,y]);}if(!full&&R()<.18)y=Math.max(a,Math.min(b,y+(R()<.5?-1:1)));}return cells;};
