 {const li=LAYERS.indexOf(layerOf(d.y));if(li>0&&!G.seenBand[li]){G.seenBand[li]=1;G.sq=(G.sq||[]).filter(q=>!/Tap it/.test(q[0]));say(LAYERS[li].hi,5500,2);}}
