const STEP=.2,ROPE_AT=1.1,MEET=1.8;
function liftTick(dt){const L=G.lift;if(!L)return;L.t+=dt;const P=G.p,n=L.path.length;
 if(L.ph==='radio'&&L.t>(L.auto?3.2:.9)){L.ph='down';L.t=0;}
 else if(L.ph==='down'){L.i=Math.min(n-2,L.t/(L.st||STEP));/* he stops one square before you */if(L.i>=n-2){L.ph='meet';L.t=0;say(pick(['Found you! Let me tie this rope to you, then follow me out.','There you are! I\'ll tie this rope on you so you can\'t slip. Up we go!','Nice tunnel! Rope on, and follow me up.']),3400);}}
 else if(L.ph==='meet'&&L.t>MEET){L.ph='out';L.t=0;L.i=n-2;L.pi=n-1;}
 else if(L.ph==='out'){/* back along the same path, you one square behind him */L.i=Math.max(0,n-2-L.t/(L.st||STEP)*1.5);L.pi=Math.min(n-1,L.i+1);if(!L.untied&&along(L.path,L.pi)[1]<=SURF-1+.01){L.untied=1;say('Made it! There, I\'ll untie you.',2500);}if(L.i<=0){L.ph='top';L.t=0;}}
 else if(L.ph==='top'&&L.t>.35){P.x=L.path[1]?L.path[1][0]:3;P.y=SURF-1;if(!supported(P.x,P.y)){let best=P.x,bd=99;for(let x=1;x<COLS-1;x++)if(solid(tile(x,SURF))&&Math.abs(x-P.x)<bd){bd=Math.abs(x-P.x);best=x;}P.x=best;}
  P.mode='idle';G.lift=null;if(G.energy<=0){G.energy=G.emax||100;G.warned=0;say('Here we are! I put a fresh battery in your lamp.');if(G.bag.length)setTimeout(tripDone,1600);return;}say(G.bag.length||G.tf.length?'Here we are! Let\'s see what you found.':'Back at the top! Call me any time.');if(G.bag.length||G.tf.length)setTimeout(tripDone,200);}}
