function onTap(e){if(G.lift&&G.lift.ph==='out'){G.lift.i=0;G.lift.ph='top';G.lift.t=0;G.lift.untied=1;return;}const r=CV.getBoundingClientRect(),ox=Math.round((r.width-TS*COLS)/2);const x=Math.floor((e.clientX-r.left-ox)/TS),y=Math.floor((e.clientY-r.top+camY)/TS);ac();tryAct(x,y);}
function onKey(e){const P=G.p,m={ArrowLeft:[-1,0],ArrowRight:[1,0],ArrowDown:[0,1],ArrowUp:[0,-1],a:[-1,0],d:[1,0],s:[0,1],w:[0,-1]}[e.key];if(!m)return;e.preventDefault();ac();tryAct(P.x+m[0],P.y+m[1]);}
function loop(now){if(RUN!==loop.run)return;if(!document.getElementById('dgRoot')){stop();return;}const dt=Math.min(.05,(now-(last||now))/1000);last=now;update(dt);liftTick(dt);draw(now);requestAnimationFrame(loop);}
window.Dig2={start(){CV=document.getElementById('dgCv');CX=CV.getContext('2d');freshState(false);try{const d=D_(),a=d&&d.at;if(a&&!window.__seed){const [x,y,e,l]=a;if(!solid(tile(x,y))&&supported(x,y)){G.p.x=G.p.fx=x;G.p.y=G.p.fy=y;G.energy=Math.max(25,Math.min(G.emax,e));G.ladders=l;LAYERS.forEach((L0,i)=>{if((i?LAYERS[i-1].to+1:SURF)<=y)G.seenBand[i]=1;});setTimeout(()=>say('Back down Dr. Quartz\'s rope, right where you left off!',4000,true),600);}d.at=null;}}catch(e){}CV.addEventListener('pointerdown',onTap);document.removeEventListener('keydown',onKey);document.addEventListener('keydown',onKey);
 const free=()=>!document.querySelector('#dgRoot .dgm.on');document.getElementById('dgBLift').onclick=()=>{if(!free())return;ac();callLift(false);};document.getElementById('dgBLad').onclick=()=>{if(!free()||G.done)return;ac();ladders();};document.getElementById('dgLClose').onclick=()=>document.getElementById('dgMLad').classList.remove('on');document.getElementById('dgTKeep').onclick=()=>{if(G.exitAfter){storeSite();G.exitAfter=0;document.getElementById('dgMTrip').classList.remove('on');if(window.Lab&&Lab.home)Lab.home();else go('world');return;}newTrip(false);};document.getElementById('dgTFresh').onclick=()=>newTrip(true);
 document.getElementById('dgBPick').onclick=()=>{if(!free()||G.done)return;ac();pickShop();};document.getElementById('dgPClose').onclick=()=>document.getElementById('dgMPick').classList.remove('on');
 document.getElementById('dgBMus').onclick=()=>{if(document.querySelector('#dgRoot .dgm.on'))return;museum();};document.getElementById('dgMusClose').onclick=()=>document.getElementById('dgMMus').classList.remove('on');
 document.getElementById('dgBFresh').onclick=()=>{if(confirmFresh())newTrip(true);};
 document.getElementById('dgRoot').addEventListener('pointerup',e=>{const b=e.target.closest('.ear');if(!b)return;e.stopPropagation();const box=b.closest('[data-say]')||b.parentElement;hear(box.dataset&&box.dataset.say||box.textContent);});
 const sets=[['dgSBright','bright'],['dgSCalm','calm'],['dgSSafe','safe'],['dgSAuto','autoRead']];sets.forEach(([id,k])=>{const b=document.getElementById(id);b.checked=!!SET[k];b.onchange=()=>{SET[k]=b.checked;saveSet();};});
 document.getElementById('dgBSet').onclick=()=>document.getElementById('dgMSet').classList.toggle('on');document.getElementById('dgSClose').onclick=()=>document.getElementById('dgMSet').classList.remove('on');
 document.getElementById('dgExit').onclick=()=>{if(G&&G.lift)return;if(G&&G.bag.length&&!G.done&&!document.querySelector('#dgRoot .dgm.on')){G.exitAfter=1;tripDone();return;}storeSite();try{SFX.tap();}catch(e){}if(window.Lab&&Lab.home)Lab.home();else go('world');};document.getElementById('dgPrint').onclick=()=>{try{window.print();}catch(e){}};
 welcome();RUN++;loop.run=RUN;last=0;requestAnimationFrame(loop);},_g:()=>G,_act:tryAct,_seed:n=>{window.__seed=n;G=null;freshState(false);},_set:(k,v)=>{SET[k]=v;},_mus:()=>MUSo(),_museum:()=>museum()};
