const DG_HTML="<div id=\"dgWrap\">\n <div id=\"dgHud\"><button class=\"big alt\" id=\"dgExit\" style=\"min-height:40px;padding:6px 12px;font-size:16px\">\ud83d\ude82 Train</button><span class=\"chip\" id=\"dgDepth\">Surface</span>\n  <div class=\"ebar\"><div id=\"dgEFill\"></div><span>\u26a1 Energy</span></div>\n  <span class=\"chip\">\ud83e\ude9c <b id=\"dgNLad\">10</b></span><span class=\"chip\">\ud83e\uddb4 <b id=\"dgNBag\">0</b></span><span class=\"chip\"><span id=\"dgCoinIc\"></span> <b id=\"dgNGold\">0</b></span>\n  <button class=\"big alt\" id=\"dgBSet\" style=\"min-height:40px;padding:6px 12px;font-size:16px\" aria-label=\"Grown-up settings\">\u2699\ufe0f</button></div>\n <canvas id=\"dgCv\"></canvas>\n <div id=\"dgBar\"><button class=\"big\" id=\"dgBLad\">\ud83e\ude9c Get ladders</button><button class=\"big\" id=\"dgBLift\">\ud83d\udcfb Call Dr. Quartz</button><button class=\"big\" id=\"dgBPick\">\u26cf\ufe0f Tools</button><button class=\"big\" id=\"dgBMus\">\ud83c\udfdb\ufe0f Museum</button><button class=\"big alt\" id=\"dgBFresh\">\ud83d\uddfa\ufe0f Fresh dig site</button></div>\n</div>\n<div id=\"dgDq\"></div>\n<div class=\"note\">Tap right next to your miner to dig or step \u00b7 tap along your row to walk \u00b7 Mac: arrow keys</div>\n<div class=\"dgm\" id=\"dgMChoice\"><div class=\"card\"><h2>\ud83e\uddb4 A fossil!</h2><p>How will you get it out?</p>\n <div class=\"row\"><button class=\"choice\" id=\"dgCBrush\"><span class=\"ic\">\ud83e\uddd1\u200d\ud83d\udd2c</span>Do it like a scientist<small>Map it, uncover it, glue it, plaster jacket. Every clue stays safe.</small></button><button class=\"choice\" id=\"dgCExpert\" style=\"display:none\"><span class=\"ic\">\ud83c\udf1f</span>Expert scientist<small>All the careful steps at once. Every clue stays safe.</small></button><button class=\"choice\" id=\"dgCPick\"><span class=\"ic\">\u26a1</span>Rush it out<small>Fast, but it will crack and a clue will be lost.</small></button></div>\n <div class=\"row\"><button class=\"big alt\" id=\"dgCLater\">Not yet</button></div></div></div>\n<div class=\"dgm\" id=\"dgMBrush\"><div class=\"card\"><div id=\"dgBSteps\" class=\"steps\"></div><h2 id=\"dgBTitle\">Map it first!</h2>\n <canvas id=\"dgBrushCv\" width=\"420\" height=\"315\"></canvas><div class=\"prog\"><div id=\"dgBProg\"></div></div>\n <p id=\"dgBTip\" class=\"tip\">\ud83d\udd0a</p><div class=\"row\" id=\"dgBBtns\"></div></div></div>\n<div class=\"dgm\" id=\"dgMTrip\"><div class=\"card\"><h2>\ud83c\udf89 Trip complete!</h2><div id=\"dgTripBody\"></div>\n <div class=\"row\"><button class=\"big\" id=\"dgTKeep\">\u26cf\ufe0f Dig again (keep my tunnels)</button><button class=\"big alt\" id=\"dgTFresh\">\ud83d\uddfa\ufe0f Fresh dig site</button><button class=\"big alt\" id=\"dgPrint\">\ud83d\udda8\ufe0f Print notebook</button></div></div></div>\n<div class=\"dgm\" id=\"dgMFresh\"><div class=\"card\"><h2>\ud83d\uddfa\ufe0f A fresh dig site?</h2><p>Your tunnels and ladders will be filled in, and there will be new fossils to find.</p>\n <div class=\"row\"><button class=\"big\" id=\"dgFYes\">Yes, fresh site</button><button class=\"big alt\" id=\"dgFNo\">Keep my tunnels</button></div></div></div>\n<div class=\"dgm\" id=\"dgMLad\"><div class=\"card\"><h2>\ud83e\ude9c Get more ladders</h2><p>Solve this and Dr. Quartz sends down <span id=\"dgLN\">3</span> ladder pieces:</p><p style=\"font-size:26px;font-weight:700\" id=\"dgLQ\"></p>\n <div class=\"row\" id=\"dgLOpts\"></div><p id=\"dgLFb\" style=\"font-weight:700;min-height:1.4em\"></p><div class=\"row\"><button class=\"big alt\" id=\"dgLBuy\"></button><button class=\"big alt\" id=\"dgLClose\">Close</button></div></div></div>\n<div class=\"dgm\" id=\"dgMPick\"><div class=\"card\"><h2>\u26cf\ufe0f Digging tools</h2><p class=\"muted\">Big tools clear the rock on top. Next to a bone, scientists always switch to small tools.</p><div id=\"dgPBody\"></div><div class=\"row\"><button class=\"big alt\" id=\"dgPClose\">Close</button></div></div></div>\n<div class=\"dgm\" id=\"dgMId\"><div class=\"card\"><h2 id=\"dgITitle\"></h2><canvas id=\"dgIdCv\" width=\"420\" height=\"240\" style=\"width:100%;max-width:420px;border:3px solid #2b2340;border-radius:14px\"></canvas><p id=\"dgITip\" class=\"tip\"></p><div class=\"row\" id=\"dgIBtns\"></div></div></div>\n<div class=\"dgm\" id=\"dgMMus\"><div class=\"card\"><h2>\ud83c\udfdb\ufe0f My museum</h2><div id=\"dgMusBody\"></div><div class=\"row\"><button class=\"big alt\" id=\"dgMusClose\">Close</button></div></div></div>\n<div class=\"dgm\" id=\"dgMSet\"><div class=\"card sets\"><h2>\u2699\ufe0f Grown-up settings</h2>\n <label><input type=\"checkbox\" id=\"dgSBright\"> Brighter caves (the deep layers stay light)</label>\n <label><input type=\"checkbox\" id=\"dgSCalm\"> Less motion and sound (no screen shake)</label>\n <label><input type=\"checkbox\" id=\"dgSSafe\"> No hazards (cracked rock never breaks)</label>\n  <label><input type=\"checkbox\" id=\"dgSAuto\"> Read everything aloud (for kids who can't read yet)</label>\n <div class=\"row\"><button class=\"big\" id=\"dgSClose\">Done</button></div></div></div>\n";
function stop(){RUN++;document.removeEventListener('keydown',onKey);try{storeSite();}catch(e){}try{if(window.speechSynthesis)speechSynthesis.cancel();}catch(e){}}
function open(){const p=MQP();if(!p){go('world');return;}try{const t=document.getElementById('toast');if(t)t.classList.remove('show');}catch(e){} /* a map toast must not cover the dig buttons */
 if(!document.getElementById('dgCss')){const st=document.createElement('style');st.id='dgCss';st.textContent=DG_CSS;document.head.appendChild(st);}
 try{if(typeof closeModal==='function')closeModal();}catch(e){}
 app.innerHTML='<div id="dgRoot">'+DG_HTML+'</div>';G=null;window.Dig2.start();}
/* Dr. Quartz says hello: the first visit explains the dig; a kid from the old cave hears where everything went */
function welcome(){const p=MQP(),d=D_();if(!p||!d)return;p.sci=p.sci||{};if(!p.sci.met){p.sci.met=true;save();}const k2=SET.grade==='k2',old=!!(p.cave&&(p.cave.trips||Object.keys(p.cave.idd||{}).length));
 if(!d.rest&&((p.cg&&p.cg.j&&Object.keys(p.cg.j).length)||(p.inner&&(p.inner.tix||[]).length))){d.rest=1;save();setTimeout(()=>say('The Crystal Garden and Ozzy\'s rides are resting for now. Your jars and tickets are saved!',6000,true),11000);}
 if(!d.met){d.met=1;save();const big=EMAX()>100;
  say(k2?'Welcome to my dig site! Tap the ground next to you to dig.':'Welcome to my dig site! Tap the ground right next to you to dig or step.',5000,true);
  setTimeout(()=>say(old?`I moved my lab out of the cave into this trailer.${big?' Your old cave batteries make your Energy bar bigger!':''}${Object.keys(p.cave.idd||{}).length?' Your minerals are in the Museum.':''}`:'See the bone scraps on the ground? A fossil may be buried below. Dig there!',6500,true),5200);}
 else if((d.wb||[]).length){say(`You brought back ${d.wb.length} bone${d.wb.length>1?'s':''}! Let's find out what ${d.wb.length>1?'they are':'it is'}.`,4000,true);setTimeout(()=>{const w=(D_()||{}).wb||[];if(w.length&&G&&!document.querySelector('#dgRoot .dgm.on')&&document.getElementById('dgMId'))identify(null,null,w[0],()=>{if(((D_()||{}).wb||[]).length)museum();});},1800);}
 else say('See the bone scraps on the ground? A fossil may be buried below. Dig there!',5000,true);}
/* the Treasures panel (Me → Treasures) shows the dig museum */
function bagHTML(p){const d=p&&p.dig;if(!d||!d.met)return '';const m=d.mus||{d:{},f:{}};const n=Object.keys(m.d||{}).length,fs=Object.keys(m.f||{}).length,w=(d.wb||[]).length;
 return `<div class="panel"><h3>🦖 Dr. Quartz's Dig Site</h3><p style="margin:0">🏛️ Museum: <b>${n}</b> of ${Object.keys(CLUES).length} dinosaurs · ✨ <b>${fs}</b> small finds${w?` · 🔬 ${w} bone${w>1?'s':''} to identify`:''}</p><p style="margin:6px 0 0;font-size:14px;opacity:.8">Take the 🚂 train to the dig site.</p></div>`;}
/* Dr. Quartz's map visit now invites you to the dig site (no more mystery rocks: any left over become coins) */
function meet(){const p=MQP();if(!p)return;if(document.getElementById('dgRoot'))return;if(document.querySelector('#modal.show')||(typeof curScreen!=='undefined'&&curScreen!=='world')){meet.n=(meet.n||0)+1;if(meet.n<40)setTimeout(meet,1500);return;}meet.n=0;try{if(window.autoPopUsed)autoPopUsed();}catch(e){} /* never on top of another card (the Daily Spin), and nothing pops over him */
 const s=p.sci=p.sci||{};const first=!s.met;try{W.path=[];W.mobs=W.mobs.filter(m=>!m.quartz);}catch(e){}
 const rel=()=>{try{const v=window.MQ_VISIT;if(v&&v.release)v.release('quartz');}catch(e){}};
 const rk=s.rocks||0;const nm=esc(String(p.name||'').split(' ')[0]);
 const lines=first?[`Hello, ${nm}! I'm <b>Dr. Quartz</b>, the town's science teacher. 🔬`,'I set up a brand-new <b>dinosaur dig site</b>, with my field lab in a trailer! Real rock layers, real fossils, real science.','Want to come and dig with me? The 🚂 train goes there any time, too.']
  :[(()=>{const dg=p.dig||{},mu=(dg.mus&&dg.mus.d)||{},ks=Object.keys(mu),best=ks.filter(k=>!mu[k].done).sort((a,b)=>mu[b].have.filter(Boolean).length-mu[a].have.filter(Boolean).length||(b==='trex')-(a==='trex'))[0],nm2={trex:'T. rex',trike:'Triceratops',dakota:'Dakotaraptor',ankylo:'Ankylosaurus',stego:'Stegosaurus',brachio:'Brachiosaurus'};return ks.length?`Welcome back, ${nm}! Your museum has <b>${ks.length} dinosaur${ks.length>1?'s':''}</b>.`+(best?` Your <b>${nm2[best]||best}</b> needs ${8-mu[best].have.filter(Boolean).length} more bone${8-mu[best].have.filter(Boolean).length>1?'s':''}! 🦴`:''):dg.site&&dg.site.dug&&/[^A]/.test(String(dg.site.dug).replace(/=+$/,''))?`Welcome back, ${nm}! Your tunnels are waiting at the <b>dig site</b>. 🦖`:`${nm}! Come and see my new <b>dinosaur dig site</b>! 🦖`;})()+(rk?` And those <b>${rk} mystery rock${rk>1?'s':''}</b> 🪨 you found? I looked at ${rk>1?'them':'it'} under my microscope: plain rock, but good collecting! Here are <b>🪙 ${rk*50}</b> coins for your work.`:'')];
 if(rk){p.coins=(p.coins||0)+rk*50;s.rocks=0;}s.met=true;save();
 let i=0;const show=()=>{const last=i>=lines.length-1;const av=(window.Quartz&&Quartz.SVG)||'🔬';
  modal(`<div class="mcard qz-card"><div class="qz-row"><div class="qz-av">${av}</div><div class="qz-bub"><b>🔬 Dr. Quartz</b><div>${lines[i]}</div></div></div><div class="row">${last?`<button class="btn ghost dark" id="qzNo">Maybe later</button><button class="btn green big" id="qzGo">🦖 Take me there!</button>`:`<button class="btn green big" id="qzNext">Next ➜</button>`}</div></div>`);
  const nx=document.getElementById('qzNext');if(nx)nx.onclick=()=>{i++;show();};
  const g=document.getElementById('qzGo');if(g)g.onclick=()=>{closeModal();rel();go('lab');};
  const no=document.getElementById('qzNo');if(no)no.onclick=()=>{closeModal();rel();toast('🚂 Take the train to the dig site any time!');};};show();}
